package com.seteffects;

import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class WarmClothingTest
{
	// Items the wiki's Warmth page says do NOT count as warm, despite looking like they should
	private static final int[] NOT_WARM = {
		ItemID.ABYSSAL_LANTERN,
		ItemID.ABYSSAL_LANTERN_BLISTERWOOD,
		ItemID.ABYSSAL_LANTERN_MAGIC,
		ItemID.ABYSSAL_LANTERN_MAPLE,
		ItemID.ABYSSAL_LANTERN_NORMAL,
		ItemID.ABYSSAL_LANTERN_NORMAL_BLUE,
		ItemID.ABYSSAL_LANTERN_NORMAL_GREEN,
		ItemID.ABYSSAL_LANTERN_NORMAL_PURPLE,
		ItemID.ABYSSAL_LANTERN_NORMAL_RED,
		ItemID.ABYSSAL_LANTERN_NORMAL_WHITE,
		ItemID.ABYSSAL_LANTERN_OAK,
		ItemID.ABYSSAL_LANTERN_REDWOOD,
		ItemID.ABYSSAL_LANTERN_WILLOW,
		ItemID.ABYSSAL_LANTERN_YEW,
		ItemID.BONE_CLAWS,
		ItemID.BUNNYEARS,
		ItemID.BURNING_AMULET_1,
		ItemID.BURNING_AMULET_2,
		ItemID.BURNING_AMULET_3,
		ItemID.BURNING_AMULET_4,
		ItemID.BURNING_AMULET_5,
		ItemID.DEVILS_ELEMENT,
		ItemID.EMBERLIGHT,
		ItemID.HAT_OF_THE_EYE,
		ItemID.HAT_OF_THE_EYE_BLUE,
		ItemID.HAT_OF_THE_EYE_GREEN,
		ItemID.HAT_OF_THE_EYE_RED,
		ItemID.HUNTING_LIGHTER_CAPE,
		ItemID.HUNTING_LIGHTER_CAPE_WORN,
		ItemID.HUNTING_LIGHT_CAPE,
		ItemID.HUNTING_LIGHT_CAPE_WORN,
		ItemID.HUNTING_STRUNG_RABBIT_FOOT,
		ItemID.LEAGUE_4_TORCH,
		ItemID.LEAGUE_RELIC_AGILITY_BOOTS,
		ItemID.RAEDWALD_HELM,
		ItemID.RAMBLE_LUMBERJACK_BOOTS,
		ItemID.RAMBLE_LUMBERJACK_LEGS,
		ItemID.RAMBLE_LUMBERJACK_TOP,
		ItemID.SCORCHING_BOW,
		ItemID.SERPENTINE_HELM_CHARGED_RED,
		ItemID.SERPENTINE_HELM_RED,
		ItemID.TOXIC_BLOWPIPE_LOADED_ORNAMENT,
		ItemID.TOXIC_BLOWPIPE_ORNAMENT,
		ItemID.XMAS17_WOM_HAT,
		ItemID.XMAS25_BEER_BELLY_SWEATER,
		ItemID.XMAS25_CONTEST_JUMPER,
		ItemID.OBSIDIAN_HELMET,
		ItemID.OBSIDIAN_PLATEBODY,
		ItemID.OBSIDIAN_PLATELEGS,
		ItemID.LEAGUE_4_RELIC_HUNTER_HAT_T1,
		ItemID.LEAGUE_4_RELIC_HUNTER_TOP_T1,
		ItemID.LEAGUE_4_RELIC_HUNTER_LEGS_T1,
		ItemID.LEAGUE_4_RELIC_HUNTER_BOOTS_T1,
		ItemID.LEAGUE_4_RELIC_HUNTER_HAT_T2,
		ItemID.LEAGUE_4_RELIC_HUNTER_TOP_T2,
		ItemID.LEAGUE_4_RELIC_HUNTER_LEGS_T2,
		ItemID.LEAGUE_4_RELIC_HUNTER_BOOTS_T2,
		ItemID.LEAGUE_4_RELIC_HUNTER_HAT_T3,
		ItemID.LEAGUE_4_RELIC_HUNTER_TOP_T3,
		ItemID.LEAGUE_4_RELIC_HUNTER_LEGS_T3,
		ItemID.LEAGUE_4_RELIC_HUNTER_BOOTS_T3};

	@Test
	public void itemsTheWikiSaysAreNotWarmAreNotCounted()
	{
		for (int id : NOT_WARM)
		{
			assertFalse("item " + id + " is on the wiki's non-warm list", WarmClothing.isWarm(id));
		}
	}

	@Test
	public void listedItemsAreCounted()
	{
		assertTrue(WarmClothing.isWarm(ItemID.SANTA_HAT));
		assertTrue(WarmClothing.isWarm(ItemID.PYROMANCER_BOOTS));
		assertTrue(WarmClothing.isWarm(ItemID.TZHAAR_CAPE_FIRE));
		assertTrue(WarmClothing.isWarm(ItemID.SKILLCAPE_MAX));
		assertTrue(WarmClothing.isWarm(ItemID.RAMBLE_LUMBERJACK_HAT));
	}

	@Test
	public void slayerHelmetsAreCountedButThePlainAbyssalWhipIsNot()
	{
		assertTrue(WarmClothing.isWarm(ItemID.SLAYER_HELM));
		assertTrue(WarmClothing.isWarm(ItemID.SLAYER_HELM_I));
		assertTrue(WarmClothing.isWarm(ItemID.ABYSSAL_WHIP_LAVA));
		assertFalse(WarmClothing.isWarm(ItemID.ABYSSAL_WHIP));
	}
}

package com.seteffects;

import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemVariationMapping;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class SetEffectsDataTest
{
	@Test
	public void noTwoSingleItemsCollapseOntoTheSameKey()
	{
		// Entries are stored under their variation-mapped id; two whose chains merge would overwrite each other
		assertEquals(SetEffectsData.SINGLE_ITEM_COUNT, SetEffectsData.SINGLE_ITEM_EFFECTS.size());
	}

	@Test
	public void everyKeyIsItsOwnVariationChainBase()
	{
		for (int key : SetEffectsData.SINGLE_ITEM_EFFECTS.keySet())
		{
			assertEquals("key " + key, key, ItemVariationMapping.map(key));
		}
	}

	@Test
	public void chargedItemsWhoseOwnIdIsNotTheirChainBaseStillResolve()
	{
		// These were registered under their charged id, which is not the chain base the lookup uses, so they
		// never showed. Both the charged and the uncharged id must find the entry now.
		Object[][] cases = {
			{ItemID.WILD_CAVE_BOW_CHARGED, ItemID.WILD_CAVE_BOW_UNCHARGED, "Craw's bow"},
			{ItemID.WILD_CAVE_WEBWEAVER_CHARGED, ItemID.WILD_CAVE_WEBWEAVER_UNCHARGED, "Webweaver bow"},
			{ItemID.WILD_CAVE_SCEPTRE_CHARGED, ItemID.WILD_CAVE_SCEPTRE_UNCHARGED, "Thammaron's sceptre"},
			{ItemID.WILD_CAVE_CHAINMACE_CHARGED, ItemID.WILD_CAVE_CHAINMACE_UNCHARGED, "Viggora's chainmace"},
			{ItemID.TOXIC_SOTD_CHARGED, ItemID.TOXIC_SOTD, "Toxic staff of the dead"},
			{ItemID.BARRONITE_MACE, ItemID.BARRONITE_MACE_BROKEN, "Barronite mace"},
			{ItemID.ANCIENT_SCEPTRE_BLOOD, ItemID.ANCIENT_SCEPTRE_BLOOD_BROKEN, "Blood ancient sceptre"},
			{ItemID.ANCIENT_SCEPTRE_ICE, ItemID.ANCIENT_SCEPTRE_ICE_BROKEN, "Ice ancient sceptre"},
			{ItemID.ANCIENT_SCEPTRE_SMOKE, ItemID.ANCIENT_SCEPTRE_SMOKE_BROKEN, "Smoke ancient sceptre"},
			{ItemID.ANCIENT_SCEPTRE_SHADOW, ItemID.ANCIENT_SCEPTRE_SHADOW_BROKEN, "Shadow ancient sceptre"}};
		for (Object[] c : cases)
		{
			for (int i = 0; i < 2; i++)
			{
				SingleItemEffect effect = SetEffectsData.SINGLE_ITEM_EFFECTS.get(ItemVariationMapping.map((Integer) c[i]));
				assertNotNull(c[2] + " (item " + c[i] + ")", effect);
				assertEquals(c[2], effect.describe().name);
			}
		}
	}
}

package com.seteffects;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Every Slayer helmet id in the game cache (plain and imbued, all recolours including the vampyric,
 * Oathplate and Radiant ones) must be recognised, and told apart correctly - a missing id means the
 * helmet silently shows no effect.
 */
public class SlayerHelmTest
{
	private static final int[] REGULAR = {
		11864, 19639, 19643, 19647, 21264, 21888, 23073, 24370, 25898, 25904, 25910, 29816, 33066, 33338, 33340};

	private static final int[] IMBUED = {
		11865, 19641, 19645, 19649, 21266, 21890, 23075, 24444,
		25177, 25179, 25181, 25183, 25185, 25187, 25189, 25191,
		25900, 25902, 25906, 25908, 25912, 25914,
		26674, 26675, 26676, 26677, 26678, 26679, 26680, 26681, 26682, 26683, 26684,
		29818, 29820, 29822, 33068, 33070, 33072,
		33439, 33441, 33443, 33445, 33447, 33449};

	@Test
	public void everyRegularHelmetIsRecognisedAsRegular()
	{
		for (int id : REGULAR)
		{
			assertTrue("not recognised: " + id, SlayerHelm.isSlayerHelm(id));
			assertEquals("wrong tier for " + id, "Slayer helmet", SlayerHelm.describe(id).name);
		}
	}

	@Test
	public void everyImbuedHelmetIsRecognisedAsImbued()
	{
		for (int id : IMBUED)
		{
			assertTrue("not recognised: " + id, SlayerHelm.isSlayerHelm(id));
			assertEquals("wrong tier for " + id, "Slayer helmet (i)", SlayerHelm.describe(id).name);
		}
	}
}

package com.seteffects;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class VanillaOnlySetsTest
{
	@Test
	public void picksOutOnlyTheSetsWeDontTrack()
	{
		String vanilla = "<col=ffffff>Dharok the Wretched:<br><br>Attacks do more damage as your hitpoints decrease.<br><br>"
			+ "<col=ffffff>Statius's Equipment:<br><br>Melee special attacks have 15% increased accuracy.<br><br>"
			+ "<col=ffffff>Zuriel's Corrupt Equipment:<br><br>Magic special attacks have 25% increased accuracy.<br><br>";

		List<EffectLine> lines = VanillaOnlySets.parse(vanilla);

		assertEquals(2, lines.size());
		assertEquals("Statius's Equipment", lines.get(0).name);
		assertEquals("Melee special attacks have 15% increased accuracy.", lines.get(0).effect);
		assertEquals("Zuriel's Corrupt Equipment", lines.get(1).name);
		assertEquals("Magic special attacks have 25% increased accuracy.", lines.get(1).effect);
	}

	@Test
	public void ignoresTextWithNoUntrackedSets()
	{
		assertTrue(VanillaOnlySets.parse("<col=ffffff>Ahrim The Blighted:<br><br>Magic Attacks have a 25% chance.<br><br>").isEmpty());
		assertTrue(VanillaOnlySets.parse("").isEmpty());
		assertTrue(VanillaOnlySets.parse(null).isEmpty());
	}

	@Test
	public void handlesTheScriptStyleTitleAndAMissingTrailingBreak()
	{
		List<EffectLine> lines = VanillaOnlySets.parse("<col=ffffff>Vesta's Equipment:</col><br><br>Melee special attacks have 15% increased accuracy.");

		assertEquals(1, lines.size());
		assertEquals("Vesta's Equipment", lines.get(0).name);
		assertEquals("Melee special attacks have 15% increased accuracy.", lines.get(0).effect);
	}
}

