package com.seteffects;

import java.lang.reflect.Method;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Every {@link EffectFamily} needs a matching per-family toggle in the config (and vice versa,
 * apart from the master toggles and the warm clothing dropdown) - a mismatched key wouldn't fail at runtime, the toggle would
 * just silently do nothing. Reflection is fine here: this is test code, not shipped plugin code.
 */
public class EffectFamilyConfigTest
{
	private static final Set<String> MASTER_TOGGLES = Set.of("showSetEffectList", "tooltips", "verbose", "warmClothing");

	@Test
	public void everyFamilyHasAMatchingConfigItemAndViceVersa()
	{
		Set<String> configKeys = new HashSet<>();
		for (Method method : SetEffectDisplayConfig.class.getDeclaredMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item != null)
			{
				assertEquals("method name should equal its keyName", method.getName(), item.keyName());
				configKeys.add(item.keyName());
			}
		}

		Set<String> familyKeys = new HashSet<>();
		for (EffectFamily family : EffectFamily.values())
		{
			assertTrue("duplicate config key " + family.configKey, familyKeys.add(family.configKey));
			assertTrue("no @ConfigItem for " + family + " (" + family.configKey + ")", configKeys.contains(family.configKey));
		}

		configKeys.removeAll(MASTER_TOGGLES);
		configKeys.removeAll(familyKeys);
		assertTrue("@ConfigItems with no EffectFamily: " + configKeys, configKeys.isEmpty());
	}

	@Test
	public void everyFamilyIsActuallyUsedByTheData()
	{
		Set<EffectFamily> used = new HashSet<>();
		SetEffectsData.ITEM_SETS.forEach(set -> used.add(set.getFamily()));
		SetEffectsData.SINGLE_ITEM_EFFECTS.values().forEach(single -> used.add(single.getFamily()));

		// Families produced by the dedicated resolvers instead of ItemSet/SingleItemEffect
		used.add(EffectFamily.VOID_KNIGHT);
		used.add(EffectFamily.SALVE_AMULET);
		used.add(EffectFamily.BLACK_MASK);
		used.add(EffectFamily.SLAYER_HELMET);
		used.add(EffectFamily.RADAS_BLESSING);
		used.add(EffectFamily.ABYSSAL_LANTERN);
		used.add(EffectFamily.GHOSTSPEAK);
		used.add(EffectFamily.GLOVES_OF_SILENCE);
		used.add(EffectFamily.RING_OF_THE_GODS);
		used.add(EffectFamily.ENCHANTED_BOLTS);
		used.add(EffectFamily.SHAYZIEN);
		used.add(EffectFamily.VANILLA_ONLY_SETS);
		used.add(EffectFamily.CAPES_OF_ACCOMPLISHMENT);
		used.add(EffectFamily.INQUISITORS);
		used.add(EffectFamily.VIRTUS);
		used.add(EffectFamily.CRYSTAL_ARMOUR);
		used.add(EffectFamily.SWAMPBARK);
		used.add(EffectFamily.BLOODBARK);
		used.add(EffectFamily.GRACEFUL);
		PerPieceSets.SkillingOutfit.ALL.forEach(outfit -> used.add(outfit.family));
		used.add(EffectFamily.AMULET_OF_THE_DAMNED);

		for (EffectFamily family : EffectFamily.values())
		{
			assertTrue(family + " is never used by any tracked item", used.contains(family));
		}
	}
}

package com.seteffects;

import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemVariationMapping;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CrystalArmourTest
{
	@Test
	public void activeCrystalPiecesAndTheirColoursCount()
	{
		// The ids on the wiki's crystal helm, crystal body and crystal legs pages
		assertEquals(23971, ItemID.CRYSTAL_HELMET);
		assertEquals(23975, ItemID.CRYSTAL_CHESTPLATE);
		assertEquals(23979, ItemID.CRYSTAL_PLATELEGS);

		assertTrue(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.CRYSTAL_HELMET));
		assertTrue(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.CRYSTAL_CHESTPLATE));
		assertTrue(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.CRYSTAL_PLATELEGS));
		assertTrue(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.CRYSTAL_HELMET_HEFIN));
		assertTrue(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.CRYSTAL_CHESTPLATE_AMLODD));
		assertTrue(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.CRYSTAL_PLATELEGS_DEADMAN));
	}

	@Test
	public void inactivePiecesDoNotCount()
	{
		assertFalse(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.CRYSTAL_HELMET_INACTIVE));
		assertFalse(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.CRYSTAL_CHESTPLATE_INACTIVE));
		assertFalse(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.CRYSTAL_PLATELEGS_INACTIVE));
		assertFalse(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.CRYSTAL_HELMET_INACTIVE_HEFIN));
	}

	@Test
	public void gauntletMinigamePiecesDoNotCount()
	{
		assertFalse(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.GAUNTLET_HELMET_T1));
		assertFalse(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.GAUNTLET_HELMET_T3));
		assertFalse(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.GAUNTLET_CHESTPLATE_T2));
		assertFalse(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.GAUNTLET_PLATELEGS_T1));
		assertFalse(PerPieceSets.CrystalArmour.isCrystalItem(ItemID.GAUNTLET_HELMET_T1_HM));
	}

	@Test
	public void everyCountedIdIsInTheCrystalArmourVariationChain()
	{
		// Guards against a wrong constant slipping in: each counted id must map to the same chain as
		// its slot's real crystal piece
		int[][] pieces = {
			{ItemID.CRYSTAL_HELMET, ItemID.CRYSTAL_HELMET_HEFIN, ItemID.CRYSTAL_HELMET_ITHELL, ItemID.CRYSTAL_HELMET_IORWERTH,
				ItemID.CRYSTAL_HELMET_TRAHAEARN, ItemID.CRYSTAL_HELMET_CADARN, ItemID.CRYSTAL_HELMET_CRWYS, ItemID.CRYSTAL_HELMET_AMLODD,
				ItemID.CRYSTAL_HELMET_DEADMAN},
			{ItemID.CRYSTAL_CHESTPLATE, ItemID.CRYSTAL_CHESTPLATE_HEFIN, ItemID.CRYSTAL_CHESTPLATE_ITHELL, ItemID.CRYSTAL_CHESTPLATE_IORWERTH,
				ItemID.CRYSTAL_CHESTPLATE_TRAHAEARN, ItemID.CRYSTAL_CHESTPLATE_CADARN, ItemID.CRYSTAL_CHESTPLATE_CRWYS,
				ItemID.CRYSTAL_CHESTPLATE_AMLODD, ItemID.CRYSTAL_CHESTPLATE_DEADMAN},
			{ItemID.CRYSTAL_PLATELEGS, ItemID.CRYSTAL_PLATELEGS_HEFIN, ItemID.CRYSTAL_PLATELEGS_ITHELL, ItemID.CRYSTAL_PLATELEGS_IORWERTH,
				ItemID.CRYSTAL_PLATELEGS_TRAHAEARN, ItemID.CRYSTAL_PLATELEGS_CADARN, ItemID.CRYSTAL_PLATELEGS_CRWYS,
				ItemID.CRYSTAL_PLATELEGS_AMLODD, ItemID.CRYSTAL_PLATELEGS_DEADMAN}};
		for (int[] slot : pieces)
		{
			int chain = ItemVariationMapping.map(slot[0]);
			for (int id : slot)
			{
				assertEquals("item " + id, chain, ItemVariationMapping.map(id));
				assertTrue("item " + id, PerPieceSets.CrystalArmour.isCrystalItem(id));
			}
		}
	}
}

package com.seteffects;

import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class NothingWornTest
{
	private static final DiaryChecks DIARIES = new DiaryChecks(() -> false, () -> false, () -> false);

	@Test
	public void nothingWornDescribesToAnEmptyList()
	{
		List<EffectLine> lines = EquippedEffects.describeEquipment(NothingWorn.INSTANCE, family -> true, true, DIARIES,
			Collections.emptyList(), () -> false);
		assertTrue(lines.isEmpty());
	}

	@Test
	public void nothingWornStillShowsTheWarmClothingTallyWhenWanted()
	{
		List<EffectLine> lines = EquippedEffects.describeEquipment(NothingWorn.INSTANCE, family -> true, false, DIARIES,
			Collections.emptyList(), () -> true);
		assertEquals(1, lines.size());
		assertEquals("Warm clothing", lines.get(0).name);
	}

	@Test
	public void hoveringAnItemWithNothingWornStillDescribesIt()
	{
		List<EffectLine> lines = EquippedEffects.describeItem(NothingWorn.INSTANCE, net.runelite.api.gameval.ItemID.BARROWS_AHRIM_HEAD,
			family -> true, false, DIARIES);
		assertEquals(1, lines.size());
		assertEquals("Ahrim's set", lines.get(0).name);
	}
}

package com.seteffects;

import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Things that let you speak to ghosts: the ghostspeak amulet (its enchanted version shares the
 * same variation chain) and the Morytania legs 2, 3 and 4 (medium, hard and elite diary), which
 * act as one when worn. The legs' chain also holds the easy legs, which don't, so they are matched
 * on the raw id. Both are one effect, so when both are worn only the legs are listed (the less
 * obvious source); see {@link EquippedEffects}.
 */
final class GhostspeakItems
{
	private static final int AMULET_CHAIN = ItemVariationMapping.map(ItemID.AMULET_OF_GHOSTSPEAK);
	private static final String TEXT = "Woooo wooo woooooo. (You can speak to ghosts!)";

	private GhostspeakItems()
	{
	}

	static boolean isAmulet(int rawItemId)
	{
		return ItemVariationMapping.map(rawItemId) == AMULET_CHAIN;
	}

	static boolean isMorytaniaLegs(int rawItemId)
	{
		return rawItemId == ItemID.MORYTANIA_LEGS_MEDIUM
			|| rawItemId == ItemID.MORYTANIA_LEGS_HARD
			|| rawItemId == ItemID.MORYTANIA_LEGS_ELITE;
	}

	static boolean isGhostspeakItem(int rawItemId)
	{
		return isAmulet(rawItemId) || isMorytaniaLegs(rawItemId);
	}

	static EffectLine describe(int rawItemId)
	{
		return new EffectLine(isMorytaniaLegs(rawItemId) ? "Morytania legs" : "Ghostspeak amulet", TEXT);
	}
}

package com.seteffects;

/** Where hovering an item shows its effect as a tooltip. */
public enum TooltipDisplay
{
	OFF("Off"),
	EQUIPMENT_WINDOW("Equipment window"),
	EVERYWHERE("Everywhere");

	private final String label;

	TooltipDisplay(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.seteffects;

import net.runelite.api.gameval.ItemID;

/**
 * All four tiers of Rada's blessing (rewards from the Kourend & Kebos Diary) collapse to one
 * {@code ItemVariationMapping} chain - confirmed via {@code item_variations.json}
 * ("radas blessing": {@code [22803, 22941, 22943, 22945, 22947]}, the dummy placeholder plus the
 * four real tiers) - so, same as the Salve amulet, distinguishing tiers needs the raw item id.
 */
final class RadasBlessing
{
	private RadasBlessing()
	{
	}

	static boolean isRadasBlessing(int rawItemId)
	{
		return rawItemId == ItemID.ZEAH_BLESSING_EASY
			|| rawItemId == ItemID.ZEAH_BLESSING_MEDIUM
			|| rawItemId == ItemID.ZEAH_BLESSING_HARD
			|| rawItemId == ItemID.ZEAH_BLESSING_ELITE;
	}

	static EffectLine describe(int rawItemId)
	{
		if (rawItemId == ItemID.ZEAH_BLESSING_ELITE)
		{
			return new EffectLine("Rada's blessing 4", "+8% chance of catching an extra fish while Fishing.");
		}

		if (rawItemId == ItemID.ZEAH_BLESSING_HARD)
		{
			return new EffectLine("Rada's blessing 3", "+6% chance of catching an extra fish while Fishing.");
		}

		if (rawItemId == ItemID.ZEAH_BLESSING_MEDIUM)
		{
			return new EffectLine("Rada's blessing 2", "+4% chance of catching an extra fish while Fishing.");
		}

		return new EffectLine("Rada's blessing 1", "+2% chance of catching an extra fish while Fishing.");
	}
}

