	}

	static int count(ItemContainer equipment)
	{
		int count = 0;
		for (Item item : equipment.getItems())
		{
			if (item != null && item.getId() > 0 && isWarm(item.getId()))
			{
				count++;
			}
		}
		return count;
	}

