package com.seteffects;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Slayer helmet and its imbued form collapse into one enormous {@link ItemVariationMapping} chain
 * along with every cosmetic recolour of both (black/green/red/purple/turquoise/hydra/twisted/jad/
 * verzik/zuk/araxyte/hooded/league, ~60 ids total, confirmed via {@code item_variations.json}) -
 * same raw-id-collapse problem as the Salve amulet and Black mask, just at a much larger scale
 * because of how many recolours exist. Rather than hand-listing all ~60 ids, membership in the
 * whole chain is detected dynamically by comparing against the known base id's own mapped value
 * (self-updating if Jagex adds another recolour to the same chain later) - only the smaller set of
 * *regular* (non-imbued) raw ids needs to be hand-listed, since anything in the chain that isn't
 * one of those is, by elimination, some imbued variant.
 */
final class SlayerHelm
{
	private static final int CHAIN_ID = ItemVariationMapping.map(ItemID.SLAYER_HELM);

	private static final Set<Integer> REGULAR_IDS = idSet(
		ItemID.SLAYER_HELM, ItemID.SLAYER_HELM_BLACK, ItemID.SLAYER_HELM_GREEN, ItemID.SLAYER_HELM_RED,
		ItemID.SLAYER_HELM_PURPLE, ItemID.SLAYER_HELM_TURQUOISE, ItemID.SLAYER_HELM_HYDRA,
		ItemID.SLAYER_HELM_TWISTED, ItemID.SLAYER_HELM_JAD, ItemID.SLAYER_HELM_VERZIK,
		ItemID.SLAYER_HELM_ZUK, ItemID.SLAYER_HELM_ARAXYTE, ItemID.SLAYER_HELM_HOODED,
		ItemID.LEAGUE_6_SLAYER_HELM1, ItemID.LEAGUE_6_SLAYER_HELM2);

	private SlayerHelm()
	{
	}

	static boolean isSlayerHelm(int rawItemId)
	{
		return ItemVariationMapping.map(rawItemId) == CHAIN_ID;
	}

	static EffectLine describe(int rawItemId)
	{
		if (REGULAR_IDS.contains(rawItemId))
		{
			return new EffectLine("Slayer helmet", "+16.67% melee accuracy and damage against your assigned Slayer task.");
		}

		return new EffectLine("Slayer helmet (i)",
			"+16.67% melee accuracy and damage, +15% for ranged and magic, against your assigned "
				+ "Slayer task. Does not stack with the salve amulet.");
	}

	private static Set<Integer> idSet(Integer... ids)
	{
		return new HashSet<>(Arrays.asList(ids));
	}
}

package com.seteffects;

import net.runelite.api.gameval.ItemID;

/**
 * Only the imbued Ring of the gods has an effect (the holy wrench's extra Prayer restoration); the
 * plain ring is just stats. All versions share one {@code ItemVariationMapping} chain, so telling
 * them apart needs the raw, unmapped item id, the same way as {@link SalveAmulet}. The three imbued
 * ids are the Nightmare Zone, Soul Wars and PvP Arena imbuing sources.
 */
final class RingOfTheGods
{
	private static final int[] IMBUED = {ItemID.NZONE_ROTG, ItemID.SW_ROTG, ItemID.PVPA_ROTG};

	private RingOfTheGods()
	{
	}

	static boolean isImbuedRing(int rawItemId)
	{
		for (int id : IMBUED)
		{
			if (id == rawItemId)
			{
				return true;
			}
		}
		return false;
	}

	static EffectLine describe()
	{
		return new EffectLine("Ring of the gods (i)", "Increases the Prayer points restored by prayer potions, like the holy wrench. Does not stack with the wrench or Prayer cape.");
	}
}

package com.seteffects;

import java.util.function.BooleanSupplier;

/**
 * Gloves of silence: +5% pickpocketing success, but the Hard Ardougne Diary's bonus is larger and
 * doesn't stack, which makes them obsolete everywhere. So the text depends on the diary, read
 * only (via the supplier) when the gloves are actually being described.
 */
final class GlovesOfSilence
{
	private GlovesOfSilence()
	{
	}

	static EffectLine describe(BooleanSupplier hardArdougneDiary)
	{
		if (hardArdougneDiary.getAsBoolean())
		{
			return new EffectLine("Gloves of silence", "This item no longer has any benefits with the completion of the hard Ardougne diary.");
		}

		return new EffectLine("Gloves of silence", "+5% chance of success when pickpocketing, made redundant by the hard Ardougne diary bonus.");
	}
}

package com.seteffects;

import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Void Knight's top/robe/gloves are shared across all three combat-style configurations, unlike
 * every other set here - looking up "which set(s) contain this item" for a shared piece would
 * list all three possible bonuses regardless of which helm (if any) is actually equipped. This
 * resolves the one style that's actually active from the currently equipped helm instead, and
 * describes only that one; not modelled as an {@link ItemSet} at all.
 */
final class VoidKnight
{
	private static final int[] TOPS = {ItemID.PEST_VOID_KNIGHT_TOP, ItemID.ELITE_VOID_KNIGHT_TOP};
	private static final int[] ROBES = {ItemID.PEST_VOID_KNIGHT_ROBES, ItemID.ELITE_VOID_KNIGHT_ROBES};

	private VoidKnight()
	{
	}

	static boolean isVoidItem(int itemId)
	{
		return contains(TOPS, itemId)
			|| contains(ROBES, itemId)
			|| itemId == ItemID.PEST_VOID_KNIGHT_GLOVES
			|| itemId == ItemID.GAME_PEST_MELEE_HELM
			|| itemId == ItemID.GAME_PEST_ARCHER_HELM
			|| itemId == ItemID.GAME_PEST_MAGE_HELM;
	}

	/**
	 * Describes whichever Void configuration is currently active, based on the equipped helm and
	 * whether the top/robe are both the Elite variant (the Elite ranged/magic bonus needs both
	 * pieces upgraded together, not just one) - always returns something, since {@link #isVoidItem}
	 * having matched something means there's always at least something worth telling the player,
	 * even if it's just "you need a helm for this to do anything".
	 */
	static EffectLine describe(ItemContainer equipment)
	{
		int helm = mappedItem(equipment, EquipmentInventorySlot.HEAD);
		if (helm != ItemID.GAME_PEST_MELEE_HELM && helm != ItemID.GAME_PEST_ARCHER_HELM && helm != ItemID.GAME_PEST_MAGE_HELM)
		{
			return new EffectLine("Void Knight (No Helm)", "Equip a void knight helm to see its effect.");
		}

		boolean elite = mappedItem(equipment, EquipmentInventorySlot.BODY) == ItemID.ELITE_VOID_KNIGHT_TOP
			&& mappedItem(equipment, EquipmentInventorySlot.LEGS) == ItemID.ELITE_VOID_KNIGHT_ROBES;

		String name;
		String effect;
		if (helm == ItemID.GAME_PEST_MELEE_HELM)
		{
			name = elite ? "Elite Void Knight (Melee)" : "Void Knight (Melee)";
			effect = elite
				? "+10% melee damage and accuracy. Elite pieces give no extra melee bonus."
				: "+10% melee damage and accuracy.";
		}
		else if (helm == ItemID.GAME_PEST_ARCHER_HELM)
		{
			name = elite ? "Elite Void Knight (Ranged)" : "Void Knight (Ranged)";
			effect = elite
				? "+12.5% ranged damage and 10% increased range accuracy."
				: "+10% ranged damage and accuracy.";
		}
		else
		{
			name = elite ? "Elite Void Knight (Magic)" : "Void Knight (Magic)";
			effect = elite
				? "+5% magic damage and +45% magic accuracy."
				: "+45% magic accuracy.";
		}

		int worn = 1; // the helm itself, already matched above
		worn += contains(TOPS, mappedItem(equipment, EquipmentInventorySlot.BODY)) ? 1 : 0;
		worn += contains(ROBES, mappedItem(equipment, EquipmentInventorySlot.LEGS)) ? 1 : 0;
		worn += mappedItem(equipment, EquipmentInventorySlot.GLOVES) == ItemID.PEST_VOID_KNIGHT_GLOVES ? 1 : 0;

		return new EffectLine(name, worn, 4, effect);
	}

	private static int mappedItem(ItemContainer equipment, EquipmentInventorySlot slot)
	{
		Item item = equipment.getItem(slot.getSlotIdx());
		return item != null ? ItemVariationMapping.map(item.getId()) : -1;
	}

	private static boolean contains(int[] ids, int itemId)
	{
		for (int id : ids)
		{
			if (id == itemId)
			{
				return true;
			}
		}
		return false;
	}
}

